import React from "react";
import {
  
  NavLink
} from "react-router-dom";

import "../styles/Home.css";

/* =========================
   SIDEBAR MENU
========================= */

const menuItems = [
  {
    name: "New order",
    path: "/",
    icon: "🛒",
  },
  {
    name: "Announcement group",
    path: "/announcements",
    icon: "◉",
  },
  {
    name: "Services",
    path: "/services",
    icon: "▣",
  },
  {
    name: "Orders",
    path: "/orders",
    icon: "👜",
  },
  {
    name: "Add funds",
    path: "/add-funds",
    icon: "pay",
  },
  {
    name: "API",
    path: "/api",
    icon: "⚒",
  },
  {
    name: "Affiliates",
    path: "/affiliates",
    icon: "♧",
  },
  {
    name: "Child panel",
    path: "/child-panel",
    icon: "♟",
  },
  {
    name: "Tickets",
    path: "/tickets",
    icon: "▰",
  },
  {
    name: "Mass order",
    path: "/mass-order",
    icon: "♧",
  },
  {
    name: "Updates",
    path: "/updates",
    icon: "🔧",
  },
];


/* =========================
   SIDEBAR
========================= */

function Sidebar() {
  return (
    <aside className="sidebar">

      {/* LOGO */}
      <div className="logo">
        <div className="logo-circle">
          👨‍👩‍👧
        </div>

        <div className="logo-text">
          <strong>GROWW</strong>
          <strong>SMM</strong>
        </div>
      </div>

      {/* NAVIGATION */}
      <nav className="navigation">

        {menuItems.map((item) => (
          <NavLink
            key={item.path}
            to={item.path}
            end={item.path === "/"}
            className={({ isActive }) =>
              `nav-item ${isActive ? "active" : ""}`
            }
          >
            <span className="nav-icon">
              {item.icon}
            </span>

            <span className="nav-label">
              {item.name}
            </span>
          </NavLink>
        ))}

      </nav>
    </aside>
  );
}

/* =========================
   TOP BAR
========================= */

function Topbar() {
  return (
    <header className="topbar">

      <div className="topbar-right">

        <button className="balance">
          ₹0
          <span>⌄</span>
        </button>

        <button className="top-link">
          Account
        </button>

        <button className="top-link">
          Logout
        </button>

      </div>

    </header>
  );
}

/* =========================
   DASHBOARD CARDS
========================= */

function DashboardCards() {
  return (
    <>
      <div className="dashboard-grid">

        <div className="info-card">

          <div className="card-icon">
            ☷
          </div>

          <div>
            <h2>satendra</h2>

            <p>
              Welcome to growwsmmpanel.com
            </p>
          </div>

        </div>


        <div className="info-card">

          <div className="card-icon people">
            ♧
          </div>

          <div>
            <h2>4072853</h2>

            <p>
              Panel orders
            </p>
          </div>

        </div>


        <div className="info-card">

          <div className="card-icon">
            ▣
          </div>

          <div>
            <h2>₹0</h2>

            <p>
              To Add fund{" "}
              <span className="red-text">
                CLICK HERE
              </span>
            </p>
          </div>

        </div>

      </div>


      <div className="notice">

        <span>
          THINGS TO BE KNOWN BEFORE PLACING THE ORDER
        </span>

        <button>
          +
        </button>

